create or replace function edoc.edoc_workspace_drafts(p_request jsonb)
returns jsonb language plpgsql stable security invoker set search_path='' as $function$
declare
 v_actor text:=p_request->>'actor_id'; v_company text:=p_request->>'company_id';
 v_search text:=coalesce(p_request->>'search',''); v_size integer:=coalesce((p_request->>'page_size')::integer,25);
 v_archived boolean:=coalesce((p_request->>'archived')::boolean,false); v_result jsonb;
begin
 if v_size not between 1 and 100 or length(v_search)>200 then
  raise exception using errcode='22023',message='workspace_drafts_filter_invalid';
 end if;
 if not exists(select 1 from edoc.users where id=v_actor and company_id=v_company and status='啟用') then
  raise exception using errcode='42501',message='workspace_drafts_actor_inactive';
 end if;
 with cloud_linked as (
  select c.*,d.id as linked_id,d.current_status as linked_status,d.source_type as linked_source,
   (coalesce(c.snapshot_json->>'officialDocumentId','')='' and coalesce(c.snapshot_json->>'currentComposeDraftId','')=''
    and coalesce(c.snapshot_json->'values'->>'#dispatchNo','')=''
    and not exists(select 1 from edoc.official_documents x where x.id=c.id or x.id=c.snapshot_json->>'draftRequestId')) as can_archive,
   row_number() over(partition by coalesce(d.id,'cloud:'||c.id) order by c.updated_at desc,c.id desc) as position
  from edoc.official_document_compose_drafts c
  left join edoc.official_documents d on d.applicant_id=c.applicant_id
   and d.id=coalesce(nullif(c.snapshot_json->>'officialDocumentId',''),nullif(c.snapshot_json->>'draftRequestId',''))
  where c.applicant_id=v_actor and c.company_id=v_company and c.archived=v_archived
 ), cloud as (
  select 'cloud:'||id as key,id,'cloud'::text as kind,coalesce(linked_source,'blank_editor') as source_type,
   coalesce(linked_status,'draft') as status,coalesce(linked_id,'') as official_id,
   coalesce(nullif(snapshot_json->'values'->>'#subject',''),nullif(snapshot_json->'values'->>'#documentPurpose',''),'未命名公文') as title,
   updated_at,revision,can_archive
  from cloud_linked where position=1 and (linked_id is null or linked_status in ('draft','rejected')) and (not v_archived or can_archive)
 ), drafts as (
  select * from cloud union all
  select 'official:'||d.id,d.id,'official',d.source_type,d.current_status,d.id,coalesce(nullif(d.subject,''),nullif(d.title,''),'未命名文件'),d.updated_at,null::integer,false
  from edoc.official_documents d where not v_archived and d.applicant_id=v_actor and d.current_status in ('draft','rejected')
   and not exists(select 1 from cloud where cloud.official_id=d.id)
 ), filtered as materialized (
  select * from drafts where v_search='' or strpos(lower(title),lower(v_search))>0 or strpos(lower(id),lower(v_search))>0
 ), page as (
  select * from filtered where not coalesce((p_request->>'summary')::boolean,false)
   and (coalesce(p_request->>'after_at','')='' or (updated_at,key)<(p_request->>'after_at',p_request->>'after_key'))
  order by updated_at desc,key desc limit v_size+1
 ) select pg_catalog.jsonb_build_object('total',(select count(*) from filtered),
  'items',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(page) order by updated_at desc,key desc) from page),'[]'::jsonb)) into v_result;
 return v_result;
end $function$;
